public class SetDiffReportTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            java.util.Set<String> before = new java.util.HashSet<>(java.util.Arrays.asList("a", "b", "c"));
            java.util.Set<String> after = new java.util.HashSet<>(java.util.Arrays.asList("b", "c", "d"));
            check("basic change log", "[ADD d, DEL a, SAME 2]", SetDiffReport.changeLog(before, after).toString());
            check("before was not modified", 3, before.size());
            check("after was not modified", 3, after.size());
            check("nothing changed", "[SAME 3]", SetDiffReport.changeLog(before, before).toString());
            check("two empty sets", "[SAME 0]",
                    SetDiffReport.changeLog(new java.util.HashSet<>(), new java.util.HashSet<>()).toString());
            check("everything added, sorted", "[ADD x, ADD y, ADD z, SAME 0]",
                    SetDiffReport.changeLog(new java.util.HashSet<>(),
                            new java.util.HashSet<>(java.util.Arrays.asList("z", "y", "x"))).toString());
            check("everything removed", "[DEL p, DEL q, SAME 0]",
                    SetDiffReport.changeLog(new java.util.HashSet<>(java.util.Arrays.asList("q", "p")),
                            new java.util.HashSet<>()).toString());
            check("adds come before deletes", "[ADD new, DEL old, SAME 1]",
                    SetDiffReport.changeLog(new java.util.HashSet<>(java.util.Arrays.asList("old", "keep")),
                            new java.util.HashSet<>(java.util.Arrays.asList("new", "keep"))).toString());
        } catch (Throwable t) {
            broke("changeLog", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

