import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class SetDiffReport {

    public static List<String> changeLog(Set<String> before, Set<String> after) {
        List<String> lines = new ArrayList<>();

        Set<String> added = new TreeSet<>(after);
        added.removeAll(before);
        for (String item : added) {
            lines.add("ADD " + item);
        }

        Set<String> removed = new TreeSet<>(before);
        removed.removeAll(after);
        for (String item : removed) {
            lines.add("DEL " + item);
        }

        Set<String> common = new TreeSet<>(before);
        common.retainAll(after);
        lines.add("SAME " + common.size());

        return lines;
    }
}
